from exo.API_scheduling import *
from exo.libs.memories import DRAM
# (Optional) standard scheduling helpers; not strictly needed here but available.
from exo.stdlib.scheduling import *

# Baseline BiCG kernel in Exo IR.
# This matches the mathematical definition:
#   s[j] = sum_i r[i] * A[i, j]
#   q[i] = sum_j A[i, j] * p[j]
@proc
def kernel_bicg_unopt(
    m: size,
    n: size,
    A: DATA_TYPE[n, m] @ DRAM,
    s: DATA_TYPE[m] @ DRAM,
    q: DATA_TYPE[n] @ DRAM,
    p: DATA_TYPE[m] @ DRAM,
    r: DATA_TYPE[n] @ DRAM,
):
    assert m >= 0
    assert n >= 0

    # Initialize s over its M entries.
    for j in seq(0, m):
        s[j] = 0.0

    # Main BiCG computation.
    # We explicitly use scalar temporaries to:
    #  - Avoid reloading r[i] on every inner-loop iteration.
    #  - Avoid reloading/storing q[i] on every iteration (keep it in a register).
    #  - Load A[i, j] only once per iteration.
    for i in seq(0, n):
        ri: DATA_TYPE
        ri = r[i]

        qi: DATA_TYPE
        qi = 0.0

        for j in seq(0, m):
            a_ij: DATA_TYPE
            a_ij = A[i, j]

            s[j] += ri * a_ij
            qi += a_ij * p[j]

        q[i] = qi


# Create an optimized version that will be exported as "kernel_bicg".
kernel_bicg = rename(kernel_bicg_unopt, "kernel_bicg")

# 1. Parallelize the standalone s-initialization loop.
#    This loop has no cross-iteration dependencies, so it can safely
#    be annotated for parallel execution (e.g., OpenMP in the backend).
kernel_bicg = parallelize_loop(kernel_bicg, "j #0")

# 2. Tile and unroll the inner j-loop of the main BiCG computation.
#    We:
#      - Divide j into (jo, ji) with a small constant tile size to improve
#        instruction-level parallelism and aid auto-vectorization.
#      - Use tail='guard' to correctly handle cases where m is not
#        divisible by the tile size.
#      - Unroll the ji-loop completely (it has a small, constant bound).
J_TILE = 4

# "j #1" refers to the second j-loop in the procedure:
#   - j #0 : the initialization loop over s
#   - j #1 : the inner loop inside the main BiCG computation
kernel_bicg = divide_loop(kernel_bicg, "j #1", J_TILE, ("jo", "ji"), tail="guard")
kernel_bicg = unroll_loop(kernel_bicg, "ji")

# 3. Final simplification pass to clean up guards and expressions.
kernel_bicg = simplify(kernel_bicg)
