/**
 * Exo BiCG driver: mirrors PolyBench/C bicg.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"

/* Include the Exo-generated kernel header. */
#include "generated/bicg/bicg.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  for (i = 0; i < m; i++)
    p[i] = (DATA_TYPE)(i % m) / m;
  for (i = 0; i < n; i++) {
    r[i] = (DATA_TYPE)(i % n) / n;
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % n)/n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base BiCG kernel: computes
#   s[j] = sum_i A[i, j] * r[i]  (i.e., s = A^T * r)
#   q[i] = sum_j A[i, j] * p[j]  (i.e., q = A * p)
@proc
def kernel_bicg(
    m: size,
    n: size,
    A: DATA_TYPE[n, m] @ DRAM,
    s: DATA_TYPE[m] @ DRAM,
    q: DATA_TYPE[n] @ DRAM,
    p: DATA_TYPE[m] @ DRAM,
    r: DATA_TYPE[n] @ DRAM,
):
    # Zero s and q in separate loops. This matches the reference
    # algorithm and makes the subsequent scheduling transformations
    # simpler and more effective.
    for j in seq(0, m):
        s[j] = 0.0
    for i in seq(0, n):
        q[i] = 0.0

    # Main BiCG computation: fused pass over A that updates both
    # s (A^T * r) and q (A * p). We iterate row-major in j to
    # stream through A and p with contiguous accesses.
    for i in seq(0, n):
        for j in seq(0, m):
            s[j] += r[i] * A[i, j]
            q[i] += A[i, j] * p[j]


# Scheduling: improve cache locality and expose ILP / vectorization
# while preserving the original mathematical meaning.

schedule = kernel_bicg

# 1) Parallelize the embarrassingly parallel initialization loops.
# These loops only write to distinct elements of s or q, so OpenMP-style
# parallelization is safe.
schedule = parallelize_loop(schedule, "j")     # parallelize s[j] = 0
schedule = parallelize_loop(schedule, "i #0")  # parallelize q[i] = 0

# 2) Tile the main (i, j) loop nest to improve data locality.
# We choose moderate tile sizes that map well to typical L1/L2 cache
# sizes on modern x86 cores. The exact values can be tuned further.
II = 32  # tile size in the i (row) dimension
JJ = 32  # tile size in the j (column) dimension

# First, tile the inner j-loop of the main computation. We target the
# second j-loop in the procedure ("j #1"), which is the one inside the
# main i-loop. The 'guard' tail strategy retains correctness for any m.
schedule = divide_loop(schedule, "j #1", JJ, ("jo", "ji"), tail="guard")

# Next, tile the main i-loop (now the second i-loop, "i #1") into
# io / ii. Again, 'guard' takes care of non-multiple sizes of n.
schedule = divide_loop(schedule, "i #1", II, ("io", "ii"), tail="guard")

# After tiling, the main computation nest has the structure:
#   for io:
#     for ii:
#       for jo:
#         for ji:
#           ... body ...
# This keeps row-major (j) accesses innermost and groups work into
# cache-sized tiles.

# 3) Unroll the innermost ji-loop to expose instruction-level
# parallelism and help the C compiler vectorize loads/stores of A,
# p, and s within each j-tile.
schedule = unroll_loop(schedule, "ji")

# The loop order io -> ii -> jo -> ji already provides good spatial
# locality for A and p while streaming s and q, so we keep it.

# Export the scheduled kernel under the original name so that the
# generated C function remains 'kernel_bicg' as expected by the driver.
kernel_bicg = schedule
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_bicg(/*ctxt=*/NULL, m, n,
	      (DATA_TYPE*)POLYBENCH_ARRAY(A),
	      (DATA_TYPE*)POLYBENCH_ARRAY(s),
	      (DATA_TYPE*)POLYBENCH_ARRAY(q),
	      (DATA_TYPE*)POLYBENCH_ARRAY(p),
	      (DATA_TYPE*)POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
